SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for calibration_workbook_data
-- ----------------------------
DROP TABLE IF EXISTS `calibration_workbook_data`;
CREATE TABLE `calibration_workbook_data`  (
  `id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `task_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '任务ID（任务id和templatecode相等那就是模板工作簿，可被多任务共享）',
  `workbook_data` longblob NULL COMMENT '工作簿二进制数据',
  `template_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '模板代码',
  `update_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最后更新用户',
  `last_access_time` timestamp NULL DEFAULT NULL COMMENT '最后访问时间戳',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `is_active` tinyint(4) NULL DEFAULT 1 COMMENT '是否活跃：1-活跃，0-已清理',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_task_id`(`task_id`) USING BTREE,
  INDEX `idx_last_access_time`(`last_access_time`) USING BTREE,
  INDEX `idx_is_active`(`is_active`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '工作簿数据表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of calibration_workbook_data
-- ----------------------------
