-- ----------------------------
-- Table structure for t_ins_info_temp
-- ----------------------------
DROP TABLE IF EXISTS `t_ins_info_temp`;
CREATE TABLE `t_ins_info_temp`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `device_serial_number` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `device_ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `connect_status` tinyint(4) NULL DEFAULT NULL COMMENT '连接状态',
  `device_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仪器名称',
  `device_model` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仪器型号',
  `device_model_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仪器型号名称',
  `device_current_status` tinyint(4) NULL DEFAULT NULL COMMENT '仪器当前状态',
  `machine_ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仪器ip',
  `device_port` int(11) NULL DEFAULT NULL COMMENT '仪器端口',
  `is_inited` tinyint(4) NULL DEFAULT NULL COMMENT '0：未完成；1：自检成功； 2：自检失败； 3：自检进行中',
  `is_activated` tinyint(4) NULL DEFAULT NULL COMMENT '激活状态，0-未激活，1-激活',
  `is_dev_opened` tinyint(4) NULL DEFAULT NULL COMMENT '0-未开机，1-已开机',
  `attachment_type` int(11) NULL DEFAULT NULL COMMENT '附件类型',
  `attachment_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '附件名称',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `create_user` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `update_user` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改者',
  `linear_segment` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '计算公式',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备信息表' ROW_FORMAT = DYNAMIC;

